// Generated by `pnpm core:fn` from packages/core/src/segments.ts. Do not edit.
// Edit the source, run the command, and commit both (CI checks they match).

// Timesheet segments (PRD 4.10 TS-01..06, LLD 06): one employee-day of facts in,
// non-overlapping segments out. Pure: no clock, no I/O, so it's property-tested
// and the rebuild job (#41) can run it anywhere.
//
// Every second of clocked-in time (plus approved manual time) lands in exactly one
// segment. Where facts overlap, precedence decides (break > pause > offline >
// away > unverified > meeting > idle > verified). Times are whole seconds; nothing
// is rounded here (TS-05/06).

import { DateTime } from "npm:luxon@3.7.2";
import type { PresenceStatus } from "./status.ts";

export type SegmentType =
  | "verified"
  | "meeting"
  | "idle"
  | "unverified"
  | "away"
  | "offline"
  | "pause"
  | "pause_over_cap"
  | "break"
  | "manual";

/** A half-open interval in whole Unix seconds: [start, end). */
export interface Span {
  start: number;
  end: number;
}

export interface Segment extends Span {
  type: SegmentType;
  /** null = Unassigned (PRJ-03). */
  projectId: string | null;
  /** Counted as worked time (TS-01; breaks only when the org pays them). */
  counted: boolean;
  /** Highlighted for the manager; never deducted automatically (TS-02). */
  flagged: boolean;
}

export interface DayInput {
  /** The employee's local calendar day (see `localDayBounds`). */
  day: Span;
  /** Facts after this moment aren't known yet; open intervals stop here. */
  now: number;
  clockSessions: { start: number; end: number | null; projectId: string | null }[];
  /** Approved manual entries only (TS-08: pending ones aren't counted). */
  manualEntries: { start: number; end: number; projectId: string | null }[];
  breaks: { start: number; end: number | null }[];
  pauses: { start: number; end: number | null }[];
  /** The server's status timeline; supplies offline, locked, meeting, idle and tamper. */
  statusPeriods: { status: PresenceStatus; start: number; end: number | null }[];
  checkins: { at: number; outcome: "pass" | "miss" | "failed" }[];
  projectSwitches: { at: number; projectId: string | null }[];
  /** Employee re-assignments while the week is draft (PRJ-04), applied last. */
  projectEdits?: { start: number; end: number; projectId: string | null }[];
  policy: {
    breaksPaid: boolean;
    /** BRK-06 caps, in seconds. */
    pauseMaxS: number;
    pauseDailyMaxS: number;
  };
}

const PRECEDENCE: SegmentType[] = [
  "break",
  "pause",
  "pause_over_cap",
  "offline",
  "away",
  "unverified",
  "meeting",
  "idle",
];

const FLAGGED = new Set<SegmentType>(["idle", "unverified", "away", "offline", "pause_over_cap"]);

/** Which segment type each server status contributes (TS-01). */
const FROM_STATUS: Partial<Record<PresenceStatus, SegmentType>> = {
  offline: "offline",
  away_locked: "away",
  in_meeting: "meeting",
  idle: "idle",
  // Capture blocked: the time couldn't be verified, so it's flagged like a miss.
  tamper: "unverified",
};

export function buildSegments(input: DayInput): Segment[] {
  const limit: Span = { start: input.day.start, end: Math.min(input.day.end, input.now) };
  if (limit.end <= limit.start) return [];
  const close = (end: number | null) => end ?? input.now;

  // Base time: clocked sessions, then approved manual entries outside them.
  const sessions = union(
    input.clockSessions.map((s) => clip({ start: s.start, end: close(s.end) }, limit)),
  );
  // Manual time never overlaps clocked time (TS-09) or itself; enforced here too.
  const manual = subtractAll(union(input.manualEntries.map((m) => clip(m, limit))), sessions);

  // Overlays, each tagged with its segment type.
  const overlays: { span: Span; type: SegmentType }[] = [];
  for (const b of input.breaks)
    overlays.push({ span: { start: b.start, end: close(b.end) }, type: "break" });
  for (const part of splitPauses(input)) overlays.push(part);
  for (const p of input.statusPeriods) {
    const type = FROM_STATUS[p.status];
    if (type) overlays.push({ span: { start: p.start, end: close(p.end) }, type });
  }
  for (const span of unverifiedWindows(input)) overlays.push({ span, type: "unverified" });

  const projectAt = projectTimeline(input);

  // Cut the base time at every boundary, classify each piece, then merge.
  const cuts = new Set<number>();
  for (const o of overlays) cuts.add(o.span.start).add(o.span.end);
  for (const s of input.projectSwitches) cuts.add(s.at);
  for (const e of input.projectEdits ?? []) cuts.add(e.start).add(e.end);
  const pieces: Segment[] = [];
  for (const base of sessions) {
    for (const span of cutAt(base, cuts)) {
      const type = classify(span, overlays);
      pieces.push(segment(span, type, projectAt(span.start), input.policy.breaksPaid));
    }
  }
  for (const m of manual) {
    const entry = input.manualEntries.find((e) => e.start <= m.start && m.end <= e.end);
    for (const span of cutAt(m, cuts)) {
      const edited = editAt(input, span.start);
      const projectId = edited !== undefined ? edited : (entry?.projectId ?? null);
      pieces.push(segment(span, "manual", projectId, input.policy.breaksPaid));
    }
  }
  return merge(pieces.sort((a, b) => a.start - b.start));
}

/** The local calendar day `isoDate` in `zone`, as whole Unix seconds. */
export function localDayBounds(isoDate: string, zone: string): Span {
  const start = DateTime.fromISO(isoDate, { zone }).startOf("day");
  return {
    start: Math.floor(start.toSeconds()),
    end: Math.floor(start.plus({ days: 1 }).toSeconds()),
  };
}

/** Total seconds per segment type, from raw seconds (TS-06). */
export function segmentTotals(segments: Segment[]) {
  let worked = 0;
  let flagged = 0;
  const byType: Partial<Record<SegmentType, number>> = {};
  for (const s of segments) {
    const seconds = s.end - s.start;
    byType[s.type] = (byType[s.type] ?? 0) + seconds;
    if (s.counted) worked += seconds;
    if (s.flagged) flagged += seconds;
  }
  return { worked, flagged, byType };
}

// --- pieces ------------------------------------------------------------------

function segment(
  span: Span,
  type: SegmentType,
  projectId: string | null,
  breaksPaid: boolean,
): Segment {
  return {
    start: span.start,
    end: span.end,
    type,
    projectId,
    counted: type !== "break" || breaksPaid,
    flagged: FLAGGED.has(type),
  };
}

function classify(span: Span, overlays: { span: Span; type: SegmentType }[]): SegmentType {
  let best: SegmentType = "verified";
  let rank = PRECEDENCE.length;
  for (const o of overlays) {
    if (o.span.start <= span.start && span.end <= o.span.end) {
      const r = PRECEDENCE.indexOf(o.type);
      if (r < rank) {
        rank = r;
        best = o.type;
      }
    }
  }
  return best;
}

/**
 * BRK-06: each pause counts up to the per-pause cap and while the day's counted
 * pause time stays under the daily cap; the rest of it is over the cap. Same
 * arithmetic as the server's `pauses.over_cap_s`.
 */
function splitPauses(input: DayInput): { span: Span; type: SegmentType }[] {
  const out: { span: Span; type: SegmentType }[] = [];
  let countedToday = 0;
  const pauses = [...input.pauses].sort((a, b) => a.start - b.start);
  for (const p of pauses) {
    const end = p.end ?? input.now;
    const duration = Math.max(0, end - p.start);
    const counted = Math.min(
      duration,
      input.policy.pauseMaxS,
      Math.max(0, input.policy.pauseDailyMaxS - countedToday),
    );
    countedToday += counted;
    if (counted > 0) out.push({ span: { start: p.start, end: p.start + counted }, type: "pause" });
    if (counted < duration)
      out.push({ span: { start: p.start + counted, end }, type: "pause_over_cap" });
  }
  return out;
}

/** From each missed or failed card being shown until the next pass (TS-01). */
function unverifiedWindows(input: DayInput): Span[] {
  const sorted = [...input.checkins].sort((a, b) => a.at - b.at);
  const out: Span[] = [];
  let openSince: number | null = null;
  for (const c of sorted) {
    if (c.outcome === "pass") {
      if (openSince !== null) out.push({ start: openSince, end: c.at });
      openSince = null;
    } else if (openSince === null) {
      openSince = c.at;
    }
  }
  if (openSince !== null) out.push({ start: openSince, end: Number.MAX_SAFE_INTEGER });
  return out;
}

/** The project in force at a moment: session start, then switches, then edits. */
function projectTimeline(input: DayInput): (t: number) => string | null {
  const switches = [...input.projectSwitches].sort((a, b) => a.at - b.at);
  const sessions = [...input.clockSessions].sort((a, b) => a.start - b.start);
  return (t) => {
    const edited = editAt(input, t);
    if (edited !== undefined) return edited;
    const session = sessions.filter((s) => s.start <= t).at(-1);
    let project = session?.projectId ?? null;
    for (const s of switches) {
      if (s.at > t) break;
      if (!session || s.at >= session.start) project = s.projectId;
    }
    return project;
  };
}

function editAt(input: DayInput, t: number): string | null | undefined {
  const edit = (input.projectEdits ?? []).filter((e) => e.start <= t && t < e.end).at(-1);
  return edit ? edit.projectId : undefined;
}

function merge(pieces: Segment[]): Segment[] {
  const out: Segment[] = [];
  for (const p of pieces) {
    const last = out.at(-1);
    if (last && last.end === p.start && last.type === p.type && last.projectId === p.projectId) {
      last.end = p.end;
    } else {
      out.push({ ...p });
    }
  }
  return out;
}

// --- spans -------------------------------------------------------------------

function clip(s: Span, to: Span): Span {
  return { start: Math.max(s.start, to.start), end: Math.min(s.end, to.end) };
}

function nonEmpty(s: Span): boolean {
  return s.end > s.start;
}

function cutAt(span: Span, cuts: Set<number>): Span[] {
  const points = [...cuts].filter((t) => t > span.start && t < span.end).sort((a, b) => a - b);
  const out: Span[] = [];
  let start = span.start;
  for (const t of points) {
    out.push({ start, end: t });
    start = t;
  }
  out.push({ start, end: span.end });
  return out;
}

/** Non-empty spans merged where they overlap or touch, in order. */
function union(spans: Span[]): Span[] {
  const sorted = spans.filter(nonEmpty).sort((a, b) => a.start - b.start);
  const out: Span[] = [];
  for (const s of sorted) {
    const last = out.at(-1);
    if (last && s.start <= last.end) last.end = Math.max(last.end, s.end);
    else out.push({ ...s });
  }
  return out;
}

/** `spans` minus everything in `holes`. */
function subtractAll(spans: Span[], holes: Span[]): Span[] {
  let out = spans;
  for (const h of holes) {
    out = out.flatMap((s) => {
      if (h.end <= s.start || h.start >= s.end) return [s];
      return [
        { start: s.start, end: Math.min(s.end, h.start) },
        { start: Math.max(s.start, h.end), end: s.end },
      ].filter(nonEmpty);
    });
  }
  return out;
}
